export function __readergoStart(host) {
  const __readergoModule = (id) => {
    if (!host || typeof host.module !== "function") {
      throw new Error("ReaderGo plugin host is not installed");
    }
    return host.module(id);
  };
  const require = (id) => __readergoModule(id);
// plugins/note-digest/src/index.ts
const { registerBrowserAgentTool,
  unregisterBrowserAgentTool } = __readergoModule("@/lib/runtime/agentToolRegistry");
var TOOL_NAME = "note_digest";
var NoteDigestPlugin = {
  manifest: {
    id: "readergo.tools.note-digest",
    name: "Note Digest",
    version: "0.1.0",
    description: "Adds a note_digest tool the agent can call for one note.",
    category: "ai",
    provides: [],
    requires: ["document-storage"],
    permissions: ["note:read"]
  },
  async activate(context) {
    registerBrowserAgentTool({
      name: TOOL_NAME,
      description: "Return a short plain-text digest of one note by id.",
      inputSchema: {
        type: "object",
        properties: { id: { type: "string" } },
        required: ["id"]
      },
      handler: async (args) => digestNote(context, args)
    });
    context.log.info("note_digest tool registered");
  },
  async deactivate() {
    unregisterBrowserAgentTool(TOOL_NAME);
  }
};
async function digestNote(context, args) {
  const id = typeof args.id === "string" ? args.id.trim() : "";
  if (!id) return { error: "id is required" };
  const notes = await context.getCapability("document-storage");
  if (!notes) return { error: "document-storage is not available" };
  const note = await notes.get(id);
  if (!note) return { error: `Note ${id} was not found` };
  const plain = String(note.content ?? "").replace(/\s+/g, " ").trim();
  return {
    id: note.id || id,
    title: note.title || id,
    digest: plain.slice(0, 400)
  };
}


  return { NoteDigestPlugin: NoteDigestPlugin };
}
